import gzip,re,os
pat=re.compile(r'(?i)[\d\.,]+\s*(?:x\s*10\^?-?\d+\s*)?(?:nM|µM|μM|uM|mM|pM|M|mol|ng/ml|µg/ml|ug/ml|mg/ml|g/l)\b|10\^?-\d+\s*M')
for f in sorted(os.listdir('studies/data/raw')):
    if 'series_matrix' in f:
        print('=====',f)
        seen=set()
        for l in gzip.open('studies/data/raw/'+f,'rt',errors='ignore'):
            if l.startswith('!series_matrix_table_begin'): break
            for cell in l.rstrip('\n').split('\t'):
                for m in pat.finditer(cell):
                    s=cell[max(0,m.start()-80):m.end()+40]
                    if s not in seen: seen.add(s); print(l.split('\t')[0],'|',s)

